macro define(name: code, body: span[code-token]) {
  let entries = parse-route-entries(body).as-span()
  validate-route-entries(entries)

  let cb-storage = code-builder/new()
  let(context) cb = cb-storage.&

  cb.write-code("type $name = either { ")
  cb.join-with(entries, ", ", fn[cb] en. {
    cb.write-token(en.name)
    if payload-type(en) is :some ty cb.write-code("($ty)")
  })
  cb.write(" }\n")

  cb.block("ns for $name", fn[cb, name, entries]. emit-parse-fn(name, entries))
  emit-print-impl(name, entries)

  cb.build()
}

fn render-sign-in-form(url: string, notice: ?string): wren/view {
  .{ title = "Sign in", url, status = :ok, body = html/markup(\{
    <main>
      <h1>Sign in</h1>
      #if notice is :some text { <p>$text</p> }
      <form method="post" action=${tenant-route:send-sign-in-link.to-string()}>
        <label>Email <input type="email" name="email" required autocomplete="email"/></label>
        <button>Email me a sign-in link</button>
      </form>
    </main>
  }) }
}

macro markup(markup: span[code-token]) {
  let cb = code-builder/new()
  cb.line("let html-markup-w: std/html/dom/markup-writer = .0")
  cb.line("let(context(impl writer)) _html-markup-out: *std/html/dom/markup-writer = html-markup-w.&")

  let emit-markup-code = internal/code-from-markup(markup)
  cb.write-code(emit-markup-code)

  cb.line("html-markup-w.to-node()")
  cb.build()
}

fn read-org(*conn): result[org-row, wren-error] {
  query[org-row]("select ${org.all-columns("o")} from org o").unique(conn).lift-error()
}

fn set-next-item-id(*conn, next-item-id: i64): result[empty, wren-error] {
  update("update org set next_item_id = $next-item-id").run(conn).lift-error()
}

fn list-budgets(*conn): result[list[budget-row], wren-error] {
  query[budget-row]("select ${budget.all-columns("b")} from budget b order by b.id").list(conn).lift-error()
}

macro define(schemas: code) {
  let image = if meta/eval[result[internal/schema-image, string]]("dbx/internal/build-schema-image($schemas)") is {
    :ok image -> image,
    :err message -> crash("dbx: the schema doesn't build: $message"),
  }
  let tables = internal/emit/spell-tables(image.tables)
  `
  let dbx-schema-image: span[u8] = ${meta/baked-value-expr(image.bytes)}

  $tables

  fn migrate-db(*dbx/conn): result[empty, dbx/db-error] { conn.migrate-db($schemas) }`
}

macro query[r](sql: span[code-token]) { internal/emit/build-statement(sql, :query, :some types/id[r]()) }

macro update(sql: span[code-token]) { internal/emit/build-statement(sql, :update, :none) }

macro update-returning[r](sql: span[code-token]) { internal/emit/build-statement(sql, :update-returning, :some types/id[r]()) }

fn gen-help-text[t](summary: string): string {
  let s = if types/schema[t] is { :struct s -> s, _ -> crash("need a struct") }
  let sb = string-builder/new()
  if summary.non-empty() sb.writeln(summary)
  sb.writeln(`supported command line arguments`)
  for s.fields {
    if get-arg-kind(it.type-id) is {
      :string -> sb.writeln(`  -${it.name} - required. (/-${it.name} to comment out)`),
      :opt-string -> sb.writeln(`  -${it.name} - optional. (/-${it.name} to comment out)`),
      :list-string -> sb.writeln(`  -${it.name} - list. (/-${it.name} to comment out)`),
    }
  }
  sb.build()
}

fn to[t](self: int-value): t {
  #if types/schema[t] is {
    :int :u8  -> self.as-u8().!,
    :int :u16 -> self.as-u16().!,
    :int :u32 -> self.as-u32().!,
    :int :u64 -> self.as-u64().!,
    :int :i8  -> self.as-i8().!,
    :int :i16 -> self.as-i16().!,
    :int :i32 -> self.as-i32().!,
    :int :i64 -> self.as-i64().!,
    _ -> crash("int-value.to: ${types/name[t]} is not an integer type"),
  }
}

fn to-string[t: codec/encode](value: t): string { to-string-with[o = codec/opts/default](value) }

fn to-string-with[t: codec/encode, o: static codec/opts](value: t): string {
  let sb = string-builder/new()
  let e: text-encoder[*string-builder] = .{ w = sb.& }
  value.encode[o = o](e)
  sb.build()
}

fn respond-playground-tuition(): http-response {
  let rows: list[list[i64]] = list/empty()
  for grade in 0.until(playground-grade-count) {
    let row: list[i64] = list/empty()
    for year in 0.until(playground-year-count) { row.push(atomic/load(find-playground-tuition(grade, year).!, :relaxed)) }
    rows.push(row)
  }
  response/complete(:ok, "application/json", json/to-string(rows))
}

ability form-value {
  fn parse(json/json): result[self, string]
  fn to-form-json(self): json/json
}

impl form-value for string {
  fn parse(json/json): result[string, string] { form/read-text(json) }
  fn to-form-json(self): json/json { :str self }
}

type name-text = { text: string }
impl wren/form-value for name-text {
  fn parse(json/json): result[name-text, string] {
    let name = wren/form/read-text(json).try.trim-ascii-space()
    if name.is-empty() or utf8/count-code-points(name) > 200 :err "A name is 1 to 200 characters." else :ok .{ text = name }
  }
  fn to-form-json(self): json/json { :str self.text }
}

type amount = { cents: i64 }
impl wren/form-value for amount {
  fn parse(json/json): result[amount, string] {
    if money/parse-dollars(wren/form/read-text(json).try) is :some cents :ok .{ cents } else :err amount-refusal
  }
  fn to-form-json(self): json/json { :str money/format-amount(self.cents) }
}

